// Moteur de Qualification & Scoring DUR (Douleur, Urgence, Reconnaissance/Ressources)
const lead = $input.first().json;

let score = 0;
const text = [lead.comment_sample, lead.bio, lead.post_content, lead.message, lead.interest].join(' ').toLowerCase();

// 1. Douleur (Max 25 pts)
const douleurKw = ['rentrée', 'financer', 'chômage', 'étudiant', 'revenu', 'indépendance', 'besoin d\'argent', 'galère'];
let dMatches = douleurKw.filter(k => text.includes(k)).length;
const scoreDouleur = Math.min(dMatches * 8, 25);

// 2. Urgence (Max 25 pts)
const urgenceKw = ['vacances', 'maintenant', 'immédiat', 'vite', 'rapide', 'disponible', 'tout de suite'];
let uMatches = urgenceKw.filter(k => text.includes(k)).length;
const scoreUrgence = Math.min(uMatches * 9, 25);

// 3. Ressources / Motivation (Max 25 pts)
const ressourceKw = ['apprendre', 'prêt', 'motivé', 'formation', 'canva', 'design', 'marketing'];
let rMatches = ressourceKw.filter(k => text.includes(k)).length;
const scoreMotivation = Math.min(rMatches * 8, 25);

// 4. Contactabilité (Max 15 pts)
let phone = (lead.phone || lead.whatsapp || lead.phone_detected || '').replace(/\D/g, '');
const hasPhone = phone.length >= 8;
const hasEmail = (lead.email || '').includes('@');
const scoreContact = (hasPhone ? 10 : 0) + (hasEmail ? 5 : 0);

// 5. Intention d'achat (Max 10 pts)
const intentKw = ['combien', 'prix', 'intéressé', 'lien', 'inscription'];
let iMatches = intentKw.filter(k => text.includes(k)).length;
const scoreIntent = Math.min(iMatches * 5, 10);

totalScore = Math.min(Math.max(scoreDouleur + scoreUrgence + scoreMotivation + scoreContact + scoreIntent, 15), 100);

let statut = 'Nouveau';
if (totalScore >= 90) statut = 'Très Chaud';
else if (totalScore >= 70) statut = 'Chaud';
else if (totalScore >= 40) statut = 'Tiède';
else statut = 'Froid';

// Nettoyage téléphone format international
let formattedPhone = hasPhone ? (phone.startsWith('22') || phone.startsWith('23') ? '+' + phone : '+229' + phone) : '';

return [{
  json: {
    nom_complet: lead.name || lead.first_name || 'Champion',
    email: lead.email || '',
    whatsapp: formattedPhone,
    source_contact: lead.source || 'Facebook Ads Library',
    centre_interet: lead.interest || 'Graphisme Canva',
    score_qualification: totalScore,
    statut_lead: statut,
    nombre_relances: 0,
    historique_interactions: `[${new Date().toISOString()}] Lead qualifié avec un score DUR de ${totalScore}/100.`,
    date_creation: new Date().toISOString()
  }
}];

// Normalisation du message entrant et détection d'objection
const body = $input.first().json.body || {};
const text = (body.text || body.message || body.messageText || '').toLowerCase();
const phone = (body.senderPhone || body.waId || body.phone || '').replace(/\D/g, '');

const objections = {
  prix: ['cher', 'pas d\'argent', 'moyens', 'cout', 'budget', 'tarif'],
  technique: ['ordinateur', 'pc', 'compliqué', 'débutant', 'technique'],
  temps: ['temps', 'occupé', 'dispo', 'horaires'],
  paiement: ['payer', 'mobile money', 'moov', 'mtn', 'orange', 'wave', 'compte'],
  confiance: ['arnaque', 'vrai', 'preuve', 'témoignage', 'sérieux']
};

let detectedType = 'discussion';
for (const [key, patterns] of Object.entries(objections)) {
  if (patterns.some(p => text.includes(p))) {
    detectedType = 'objection_' + key;
    break;
  }
}

if (text.includes('lien') || text.includes('acheter') || text.includes('comment faire pour payer')) {
  detectedType = 'ready_to_buy';
}

return [{
  json: {
    sender_phone: '+' + phone,
    message_recu: text,
    type_objection: detectedType,
    received_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body || {};
const contact = body.contact || {};
const email = contact.email || body.email || body.customer_email || 'client@example.com';
const name = contact.first_name ? (contact.first_name + ' ' + (contact.surname || '')) : (body.customer_name || 'Nouveau Client');
let phone = (contact.phone || body.customer_phone || '').replace(/\D/g, '');
let formattedPhone = phone.length >= 8 ? (phone.startsWith('22') ? '+' + phone : '+229' + phone) : '';

return [{
  json: {
    Nom_Complet: name,
    Email: email,
    WhatsApp: formattedPhone,
    Produit_Achete: body.product_name || 'Pack Digital Starter',
    Montant_Paye: body.amount || 15000,
    Date_Achat: new Date().toISOString(),
    Etat_Utilisation: 'Pas encore commencé',
    Satisfaction_NPS: null,
    Ventes_Additionnelles_Proposees: false,
    Statut_Ambassadeur: 'Sollicité',
    Lien_Affilie: `https://sagbodavid.com/affilie?ref=${formattedPhone}`
  }
}];
